'use strict';
const EXAM_KEY='portfolio-school-planner-exams-v1';
let exams=[];
function localDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function examDays(start,end){return daysLeft(end,new Date(start+'T12:00:00'))+1;}
function validExam(e){return e&&typeof e.id==='string'&&typeof e.title==='string'&&typeof e.course==='string'&&typeof e.goal==='string'&&validDate(e.start)&&validDate(e.due)&&e.start<=e.due&&Array.isArray(e.sessions)&&e.sessions.every(d=>validDate(d)&&d>=e.start&&d<=e.due);}
try{const saved=JSON.parse(localStorage.getItem(EXAM_KEY)||'[]');if(!Array.isArray(saved)||!saved.every(validExam))throw Error();exams=saved;}catch{el('exam-notice').textContent='Saved exam plans could not be read.';}
function saveExams(){try{localStorage.setItem(EXAM_KEY,JSON.stringify(exams));el('exam-notice').textContent='';}catch{el('exam-notice').textContent='Your changes could not be saved. Keep this page open to retain them.';}renderExams();render();}
function examProgress(e,today=localDay()){const total=examDays(e.start,e.due);const completed=new Set(e.sessions.filter(d=>d<=today)).size;const expected=today<e.start?0:examDays(e.start,today>e.due?e.due:today);return {total,completed,expected,percent:Math.round(completed/total*100)};}
function renderExams(){el('exam-count').textContent=exams.length;const list=el('exam-list');list.replaceChildren();if(!exams.length){const empty=node('div',undefined,'empty');empty.append(node('strong','Build a daily study habit.'),node('p','Add an exam and choose when your study plan begins.'));list.append(empty);return;}const today=localDay();for(const e of [...exams].sort((a,b)=>a.due.localeCompare(b.due))){const card=node('section',undefined,'entry exam-card'),head=node('div',undefined,'exam-card-heading'),title=node('div');title.append(node('h3',e.title));if(e.course)title.append(node('p',e.course,'exam-help'));const remove=node('button','×','delete');remove.setAttribute('aria-label','Delete exam plan: '+e.title);remove.addEventListener('click',()=>{exams=exams.filter(x=>x.id!==e.id);saveExams();});head.append(title,remove);card.append(head,node('p','Daily goal: '+e.goal,'exam-goal'));if(e.done)card.append(node('p','Exam completed','exam-progress'));const fmt=d=>new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date(d+'T12:00:00'));card.append(node('p',fmt(e.start)+' – '+fmt(e.due)+' · '+(daysLeft(e.due)<0?'Exam date passed':daysLeft(e.due)===0?'Exam today':'Exam in '+daysLeft(e.due)+' days'),'exam-help'));const p=examProgress(e,today),progress=node('progress');progress.max=p.total;progress.value=p.completed;progress.setAttribute('aria-label',e.title+' study progress');card.append(progress,node('p',`${p.completed} of ${p.total} study days completed · ${p.percent}%`,'exam-progress'));card.append(node('p',today<e.start?'Your study plan has not started yet.':p.completed>=p.expected?'You’re on track.':`${p.expected-p.completed} study day${p.expected-p.completed===1?'':'s'} not checked off so far.`,'exam-help'));if(today>=e.start){const form=node('form',undefined,'study-checkin'),dateBox=node('div'),label=node('label','Study date'),date=node('input');date.type='date';date.required=true;date.id='study-'+e.id;label.htmlFor=date.id;date.min=e.start;date.max=today<e.due?today:e.due;date.value=date.max;dateBox.append(label,date);const button=node('button');button.type='submit';const update=()=>{button.textContent=e.sessions.includes(date.value)?'Undo check-in':'Mark studied';};date.addEventListener('input',update);update();form.append(dateBox,button);form.addEventListener('submit',event=>{event.preventDefault();const day=date.value;if(!validDate(day)||day<e.start||day>e.due||day>localDay())return;const index=e.sessions.indexOf(day);if(index===-1)e.sessions.push(day);else e.sessions.splice(index,1);saveExams();if(index===-1)window.celebrate?.("study");});card.append(form);}if(e.sessions.length){const details=node('details'),summary=node('summary','Study history'),history=node('div',undefined,'study-history');for(const day of [...new Set(e.sessions)].sort().reverse())history.append(node('span',fmt(day)));details.append(summary,history);card.append(details);}list.append(card);}}
window.getExamDeadlines=()=>exams.map(e=>({id:'exam-'+e.id,examId:e.id,title:e.title,course:e.course,due:e.due,done:Boolean(e.done)}));
window.setExamDone=(id,done)=>{const exam=exams.find(e=>e.id===id);if(exam){exam.done=Boolean(done);saveExams();}};
window.deleteExam=id=>{exams=exams.filter(e=>e.id!==id);saveExams();};
el('exam-start').value=localDay();
el('exam-form').addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const exam={id:crypto.randomUUID(),title:data.title.trim(),course:data.course.trim(),goal:data.goal.trim(),start:data.start,due:data.due,sessions:[]};if(!validExam(exam)||!exam.title||!exam.goal){el('exam-notice').textContent='Enter an exam and daily goal, with an exam date on or after your study start date.';return;}exams.push(exam);saveExams();event.currentTarget.reset();el('exam-start').value=localDay();el('exam-title').focus();});
for(const view of ['deadlines','exams'])el(view+'-tab').addEventListener('click',()=>{for(const name of ['deadlines','exams']){el(name+'-panel').hidden=name!==view;el(name+'-tab').setAttribute('aria-pressed',String(name===view));}document.querySelector('h1').textContent=view==='exams'?'Your exam prep.':'Your deadlines.';if(view==='exams')renderExams();render();});
window.addEventListener('storage',event=>{if(event.key===EXAM_KEY){try{const saved=JSON.parse(event.newValue||'[]');if(Array.isArray(saved)&&saved.every(validExam)){exams=saved;renderExams();render();}}catch{}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderExams();render();});setInterval(renderExams,60000);renderExams();render();



